/// <summary>
/// Gets the number sequence for Custom transaction number.
/// </summary>
/// <returns>
/// Number sequence got.
/// </returns>
public static NumberSequenceReference numRefRebateCustomTransId()
{
    NumberSeqScope scope = NumberSeqScopeFactory::createDataAreaScope(curext());
    return NumberSeqReference::findReference(extendedTypeNum(METRebateTransId), scope);
}
